    if(!caseId&&!messageId&&!reviewId){caseLinkKey='';return;}
    if(caseVersion&&(!/^[1-9]\d*$/.test(caseVersion)||!Number.isSafeInteger(Number(caseVersion))||!caseId||!messageId||reviewId)){notice(caseLinkText('invalid'));return true;}
